  "sel.methods.note": { en: "Through <code>bind:this</code>. The list does not open on focus.", ru: "Через <code>bind:this</code>. Список при фокусе не открывается.", zh: "通过 <code>bind:this</code> 调用。聚焦时不会打开列表。" },
  "contrib.ai": { en: "AI tools were used during development to help with code, tests, and documentation. All code was manually reviewed and tested.", ru: "В ходе разработки использовался ИИ для помощи в коде, тестах и документации. Весь код прошёл ручную проверку и тестирование.", zh: "开发过程中使用了 AI 辅助编写代码、测试和文档，所有代码均经过人工审查与测试。" },
  "contrib.h.ai": { en: "Use of AI", ru: "Использование ИИ", zh: "AI 的使用" },
