  "contrib.s1": { en: "Specification: a comparison of API and behaviour, and a scope decision.", ru: "Спецификация: сравнение API и поведения, решение о составе.", zh: "规格说明：对比 API 与行为，并确定范围。" },
  "contrib.s2": { en: "Agreement on the scope and the disputed decisions.", ru: "Согласование состава и спорных решений.", zh: "就范围和有争议的决定达成一致。" },
