  "hero.lead": { en: "An independent implementation built with runes and snippets. Typed, accessible, with design tokens and a dark theme.", ru: "Независимая реализация на Runes и snippets. Типизированная, доступная, с дизайн-токенами и тёмной темой.", zh: "基于 Runes 与 snippets 的独立实现。带完整类型、注重无障碍，并提供设计令牌和暗色主题。" },
  "hero.t1": { en: "Ant Design–style components for", ru: "Компоненты в стиле Ant Design для", zh: "Ant Design 风格的" },
  "hero.t2": { en: "", ru: "", zh: "组件库" },
  "home.title": { en: "svelte-ant-design — Ant Design–style components for Svelte 5", ru: "svelte-ant-design — компоненты в стиле Ant Design для Svelte 5", zh: "svelte-ant-design — Ant Design 风格的 Svelte 5 组件库" },
  "intro.callout": { en: "The project is a community implementation of the Ant Design design language and is not affiliated with its authors. The API is inspired by Ant Design (MIT); the implementation is original for Svelte.", ru: "Проект — независимая реализация дизайн-языка Ant Design и не связан с его авторами. API вдохновлён Ant Design (MIT), реализация оригинальная для Svelte.", zh: "本项目是 Ant Design 设计语言的社区实现，与其作者团队无隶属关系。API 受 Ant Design（MIT）启发，实现为面向 Svelte 的原创代码。" },
  "intro.cta": { en: "Install the package", ru: "Установить пакет", zh: "安装本包" },
  "intro.e1": { en: "Svelte 5 is a required peer dependency.", ru: "Svelte 5 — обязательная peer-зависимость.", zh: "需要 Svelte 5 作为 peer 依赖。" },
  "intro.e2": { en: "Checked manually on a minimal app (SvelteKit 3, Vite 8): the build, server-side rendering and hydration work.", ru: "Проверено вручную на минимальном приложении (SvelteKit 3, Vite 8): сборка, серверный рендеринг и гидрация работают.", zh: "已在最小示例应用（SvelteKit 3、Vite 8）上手动验证：构建、服务端渲染与水合均可正常工作。" },
  "intro.e3": { en: "Modern browsers. Automated tests currently run only in Chromium.", ru: "Современные браузеры. Автоматические тесты пока запускаются только в Chromium.", zh: "现代浏览器。目前自动化测试仅在 Chromium 中运行。" },
  "intro.f1": { en: "Written from scratch for Svelte 5: runes, snippets and callbacks.", ru: "Написано с нуля для Svelte 5: Runes, snippets и колбэки.", zh: "为 Svelte 5 从零编写：Runes、snippets 与回调。" },
  "intro.f2": { en: "Strict TypeScript types for props and values.", ru: "Строгие типы TypeScript для свойств и значений.", zh: "为属性及取值提供严格的 TypeScript 类型。" },
  "intro.f3": { en: "Native elements, focus handling and an accessible colour set.", ru: "Нативные элементы, управление фокусом и набор доступных цветов.", zh: "使用原生元素，注重焦点处理，并提供无障碍配色。" },
  "intro.f4": { en: "Design tokens as CSS variables and a dark theme.", ru: "Дизайн-токены на CSS-переменных и тёмная тема.", zh: "基于 CSS 变量的设计令牌与暗色主题。" },
  "intro.f5": { en: "No dependencies except Svelte 5 (peer).", ru: "Без зависимостей, кроме Svelte 5 (peer).", zh: "除 Svelte 5（peer 依赖）外没有其他依赖。" },
